sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.view = 'form';
    c.submitting = false;
    c.serverErrors = [];

    // Pre-fill form from URL parameters if available
    var pre = c.data.prefill || {};
    c.form = {
        short_description: pre.short_description || '',
        description: '',
        exception_type: pre.category || '',
        location: pre.location || '',
        severity: pre.severity || ''
    };

    c.submit = function() {
        c.serverErrors = [];

        // Client-side validation
        if (!c.form.short_description || !c.form.short_description.trim()) {
            c.serverErrors.push('Short Description is required.');
        }
        if (!c.form.exception_type) {
            c.serverErrors.push('Exception Type is required.');
        }
        if (!c.form.severity) {
            c.serverErrors.push('Severity is required.');
        }
        if (c.serverErrors.length > 0) return;

        c.submitting = true;
        c.data.action = 'create';
        c.data.short_description = c.form.short_description;
        c.data.description = c.form.description;
        c.data.exception_type = c.form.exception_type;
        c.data.location = c.form.location;
        c.data.severity = c.form.severity;

        c.server.update().then(function() {
            c.submitting = false;
            var result = c.data.submitResult;
            if (result && result.success) {
                c.view = 'success';
                c.data.action = null;
            } else if (result && result.errors) {
                c.serverErrors = result.errors;
                c.data.action = null;
            }
        });
    };

    c.reset = function() {
        c.form = {
            short_description: '',
            description: '',
            exception_type: '',
            location: '',
            severity: ''
        };
        c.serverErrors = [];
        c.view = 'form';
    };

    c.viewDetail = function() {
        if (c.data.submitResult && c.data.submitResult.sys_id) {
            window.location.href = '?id=x_1956908_wareho_0_detail&record_id=' + c.data.submitResult.sys_id;
        }
    };

    c.goHome = function() {
        window.location.href = '?id=wei_landing';
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=DM+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --wei-bg:         #EEECEA;
  --wei-primary:    #5B4BF5;
  --wei-primary-dk: #4438D6;
  --wei-primary-lt: #EAE8FE;
  --wei-text:       #0F0F0F;
  --wei-muted:      #6B6B6B;
  --wei-border:     #D8D4D0;
  --wei-card:       #FFFFFF;
  --wei-radius:     12px;
  --wei-shadow:     0 2px 12px rgba(91,75,245,0.08);
  --wei-success:    #22C55E;
  --wei-warning:    #F59E0B;
  --wei-danger:     #EF4444;
  --wei-info:       #3B82F6;
  --ff-head:        'Playfair Display', Georgia, serif;
  --ff-body:        'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

body, .sp-widget, .portal-page {
  font-family: var(--ff-body) !important;
  background-color: var(--wei-bg) !important;
  color: var(--wei-text) !important;
}

h1,h2,h3,h4,h5,h6 {
  font-family: var(--ff-head) !important;
}

.create-exc-widget {
  max-width: 820px;
  margin: 0 auto;
}
.create-header {
  background: var(--wei-primary) !important;
  color: #fff;
  border: none;
  border-radius: var(--wei-radius) var(--wei-radius) 0 0 !important;
}
.create-header .panel-title {
  font-family: var(--ff-head) !important;
  font-weight: 800 !important;
  color: #fff;
  font-size: 18px;
}
.panel {
  border-radius: var(--wei-radius) !important;
  box-shadow: var(--wei-shadow) !important;
  border-color: var(--wei-border) !important;
}
.form-group label {
  font-family: var(--ff-body) !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.07em !important;
  color: var(--wei-text) !important;
}
.form-control {
  border-radius: 8px !important;
  border-color: var(--wei-border) !important;
  font-family: var(--ff-body) !important;
  font-size: 14px !important;
}
.form-control:focus {
  border-color: var(--wei-primary) !important;
  box-shadow: 0 0 0 3px var(--wei-primary-lt) !important;
}
.btn-primary {
  background: var(--wei-primary) !important;
  border-color: var(--wei-primary) !important;
  color: #fff !important;
  border-radius: 8px !important;
  font-family: var(--ff-body) !important;
  font-weight: 700 !important;
  padding: 10px 28px !important;
  letter-spacing: 0.05em !important;
}
.btn-primary:hover { background: var(--wei-primary-dk) !important; border-color: var(--wei-primary-dk) !important; }
.btn-default {
  border-radius: 8px !important;
  font-family: var(--ff-body) !important;
}
.form-actions {
  padding-top: 16px;
  border-top: 1.5px solid var(--wei-border);
}
.success-view { padding: 48px 20px; text-align: center; }
.success-view .fa-check-circle { color: var(--wei-success) !important; font-size: 56px !important; margin-bottom: 18px !important; }
.exc-number { color: var(--wei-primary) !important; font-weight: 800 !important; font-family: var(--ff-head) !important; }

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    data.submitResult = null;

    // Read URL query parameters for pre-fill
    data.prefill = {
        category: ($sp.getParameter('category') || $sp.getParameter('type') || '').trim(),
        severity: ($sp.getParameter('severity') || '').trim(),
        location: ($sp.getParameter('location') || '').trim(),
        short_description: ($sp.getParameter('short_desc') || $sp.getParameter('short_description') || '').trim()
    };

    // Exception type choices
    data.typeChoices = [
        { value: 'damaged_goods', label: 'Damaged Goods' },
        { value: 'inventory_mismatch', label: 'Inventory Mismatch' },
        { value: 'equipment_malfunction', label: 'Equipment Malfunction' },
        { value: 'process_error', label: 'Process Error' },
        { value: 'safety_incident', label: 'Safety Incident' },
        { value: 'other', label: 'Other' }
    ];

    // Severity choices
    data.severityChoices = [
        { value: 'critical', label: 'Critical' },
        { value: 'high', label: 'High' },
        { value: 'medium', label: 'Medium' },
        { value: 'low', label: 'Low' }
    ];

    // Handle form submission
    if (input && input.action === 'create') {
        var errors = [];
        if (!input.short_description || (input.short_description + '').trim() === '') {
            errors.push('Short Description is required.');
        }
        if (!input.exception_type) {
            errors.push('Exception Type is required.');
        }
        if (!input.severity) {
            errors.push('Severity is required.');
        }

        if (errors.length > 0) {
            data.submitResult = { success: false, errors: errors };
            return;
        }

        var gr = new GlideRecord(tableName);
        gr.initialize();
        gr.setValue('short_description', (input.short_description + '').trim());
        gr.setValue('description', (input.description || '').trim());
        gr.setValue('exception_type', input.exception_type);
        gr.setValue('location', (input.location || '').trim());
        gr.setValue('severity', input.severity);
        gr.setValue('reported_by', gs.getUserID());
        gr.setValue('status', 'new');

        var sysId = gr.insert();
        if (sysId) {
            data.submitResult = {
                success: true,
                sys_id: sysId + '',
                number: gr.getValue('number') || 'Created'
            };
        } else {
            data.submitResult = { success: false, errors: ['Failed to create record. Check permissions.'] };
        }
    }
})();
